21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
28	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
29	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
30	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
31	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
32	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
33	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
34	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
35	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
36	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
37	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
38	    @Mapping(target = "capacityWarning", expression = "java(formatCapacityWarning(owner))")
39	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
40	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
41	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
42	    @Mapping(target = "ownerSegment", expression = "java(formatOwnerSegment(owner))")
43	    OwnerDto toOwnerDto(Owner owner);
44	
45	    /**
46	     * Derive an owner's marketing segment, formatted {@code "<TIER>_<AREA>"}. The tier is
47	     * {@code "PREMIUM"} when the owner's {@code membershipLevel} (see
48	     * {@link #formatMembershipLevel(Owner)}) is {@code 3} or more, otherwise {@code "STANDARD"}.
49	     * The area is {@code "METRO"} when the owner's locality (see {@link #formatLocality(Owner)}) is
50	     * a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}. Returns one of
51	     * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or
52	     * {@code "STANDARD_REGIONAL"}; {@code null} only when the owner is {@code null}.
53	     */
54	    default String formatOwnerSegment(Owner owner) {
55	        if (owner == null) {
56	            return null;
57	        }
58	        Integer level = formatMembershipLevel(owner);
59	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
60	        String area = Regions.isKnownRegion(formatLocality(owner)) ? "METRO" : "REGIONAL";
61	        return tier + "_" + area;
62	    }
63	
64	    /**
65	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
66	     * (e.g. for owners created before the flag existed) to {@code false} so the response
67	     * always carries an explicit boolean.
68	     */
69	    default Boolean formatPossibleDuplicate(Owner owner) {
70	        if (owner == null) {
71	            return null;
72	        }
73	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
74	    }
75	
76	    /**
77	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
78	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
79	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
80	     * birth date or its registration date is absent, since the band cannot be derived without both
81	     * dates.
82	     */
83	    default String formatAgeBand(Owner owner) {
84	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
85	            return null;
86	        }
87	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
88	        if (age < 18) {
89	            return "MINOR";
90	        }
91	        if (age < 65) {
92	            return "ADULT";
93	        }
94	        return "SENIOR";
95	    }
96	
97	    /**
98	     * Derive an owner's preferred contact channel from its stored contact details:
99	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
100	     */
101	    default String formatContactPreference(Owner owner) {
102	        if (owner == null) {
103	            return null;
104	        }
105	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
106	        return hasEmail ? "EMAIL" : "PHONE";
107	    }
108	
109	    /**
110	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
111	     * (e.g. for owners created before the flag existed) to {@code false} so the response
112	     * always carries an explicit boolean.
113	     */
114	    default Boolean formatBulkSignupWarning(Owner owner) {
115	        if (owner == null) {
116	            return null;
117	        }
118	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
119	    }
120	
121	    /**
122	     * Resolve an owner's capacity-warning flag, coalescing a {@code null} stored value
123	     * (e.g. for owners created before the flag existed) to {@code false} so the response
124	     * always carries an explicit boolean.
125	     */
126	    default Boolean formatCapacityWarning(Owner owner) {
127	        if (owner == null) {
128	            return null;
129	        }
130	        return Boolean.TRUE.equals(owner.getCapacityWarning());
131	    }
132	
133	    /**
134	     * Derive an owner's locality from its {@code memberId}: the leading {@code <REGION>} segment
135	     * (the run of letters before the 2-digit fiscal year), which is the region code derived from
136	     * the owner's postcode. For an owner that has not yet been assigned a member id, the region is
137	     * derived directly from the postcode (see {@link Regions#forPostcode}), yielding the same value
138	     * the id would carry. Returns {@code null} only when the owner itself is {@code null}.
139	     */
140	    default String formatLocality(Owner owner) {
141	        if (owner == null) {
142	            return null;
143	        }
144	        String region = memberIdRegion(owner.getMemberId());
145	        if (region != null) {
146	            return region;
147	        }
148	        return Regions.forPostcode(owner.getPostcode());
149	    }
150	
151	    /**
152	     * The leading {@code <REGION>} segment of a {@code memberId}: its maximal prefix of letters,
153	     * which precedes the 2-digit fiscal year. Returns {@code null} when the member id is
154	     * {@code null} (so callers can fall back to deriving the region from the postcode).
155	     *
156	     * <p>Declared {@code private} so MapStruct does not pick it up as an automatic {@code String ->
157	     * String} conversion and apply it to every string property.
158	     */
159	    private String memberIdRegion(String memberId) {
160	        if (memberId == null) {
161	            return null;
162	        }
163	        int i = 0;
164	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
165	            i++;
166	        }
167	        return memberId.substring(0, i);
168	    }
169	
170	    /**
171	     * Derive an owner's timezone as the IANA name mapped from its locality/region via a fixed
172	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
173	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
174	     * is {@code null} or its region is not in the table.
175	     */
176	    default String formatTimezone(Owner owner) {
177	        if (owner == null) {
178	            return null;
179	        }
180	        return Regions.timezoneForRegion(formatLocality(owner));
181	    }
182	
183	    /**
184	     * Compute an owner's membership points. Points start at {@code 0} and gain: {@code 2} when an
185	     * email address is present; {@code 1} when the owner has no namesakes (its
186	     * {@code namesakeCount} is {@code 0}); {@code 2} for a household of three or more members (the
187	     * owner plus its pets); and {@code 3} when the owner's tenure (the number of fiscal years
188	     * elapsed since its {@code registrationDate}'s fiscal year) exceeds {@code 1}. A null or absent
189	     * namesake count is treated as not being zero, so it contributes nothing.
190	     */
191	    default Integer formatMembershipPoints(Owner owner) {
192	        if (owner == null) {
193	            return null;
194	        }
195	        int points = 0;
196	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
197	        if (hasEmail) {
198	            points += 2;
199	        }
200	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
201	        if (uniqueName) {
202	            points += 1;
203	        }
204	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
205	        if (householdSize >= 3) {
206	            points += 2;
207	        }
208	        LocalDate registrationDate = owner.getRegistrationDate();
209	        if (registrationDate != null
210	            && BusinessDays.fiscalYearEndYear(LocalDate.now())
211	                - BusinessDays.fiscalYearEndYear(registrationDate) > 1) {
212	            points += 3;
213	        }
214	        return points;
215	    }
216	
217	    /**
218	     * Determine an owner's membership level, a number from {@code 1} to {@code 4} derived from its
219	     * membership points (see {@link #formatMembershipPoints(Owner)}): level {@code 1} for
220	     * {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}
221	     * and {@code 4} for {@code 6} or more.
222	     *
223	     * <p>The level is then capped by the owner's {@code membershipLevelCap} when one is present (see
224	     * {@link Owner#getMembershipLevelCap()}): a new owner's level may not exceed one above the
225	     * current maximum level among its existing household members, so the returned value is the
226	     * smaller of the points-derived level and the cap. A {@code null} cap means no household ceiling
227	     * applies and the points-derived level is returned unchanged.
228	     */
229	    default Integer formatMembershipLevel(Owner owner) {
230	        if (owner == null) {
231	            return null;
232	        }
233	        int points = formatMembershipPoints(owner);
234	        int level;
235	        if (points <= 1) {
236	            level = 1;
237	        }
238	        else if (points <= 3) {
239	            level = 2;
240	        }
241	        else if (points <= 5) {
242	            level = 3;
243	        }
244	        else {
245	            level = 4;
246	        }
247	        Integer cap = owner.getMembershipLevelCap();
248	        if (cap != null && cap < level) {
249	            return cap;
250	        }
251	        return level;
252	    }
253	
254	    /**
255	     * Format an owner's fiscal year as {@code "FY<YY>"}, where {@code YY} is the 2-digit fiscal
256	     * year. The value is read from the {@code <FY>} segment of the owner's {@code memberId} (the
257	     * two digits immediately after the leading region segment), which is the fiscal year the
258	     * owner's (business-day-adjusted) {@code registrationDate} falls in. The fiscal year starts on
259	     * 1 July and is named by the calendar year in which it ends, so a registration date of
260	     * {@code 2026-07-01} is {@code "FY27"} while {@code 2026-06-30} is {@code "FY26"}. For an owner
261	     * with no member id yet, it falls back to deriving the fiscal year directly from the
262	     * registration date. Returns {@code null} when the owner, or both its member id and
263	     * registration date, are absent.
264	     */
265	    default String formatFiscalYear(Owner owner) {
266	        if (owner == null) {
267	            return null;
268	        }
269	        String memberId = owner.getMemberId();
270	        if (memberId != null) {
271	            int start = memberIdRegion(memberId).length();
272	            if (start + 2 <= memberId.length()) {
273	                return "FY" + memberId.substring(start, start + 2);
274	            }
275	        }
276	        if (owner.getRegistrationDate() == null) {
277	            return null;
278	        }
279	        return String.format("FY%02d", BusinessDays.fiscalYearEndYear(owner.getRegistrationDate()) % 100);
280	    }
281	
282	    /**
283	     * Format an owner's stored E.164 telephone for humans as the country code, a space, then the
284	     * national digits grouped in threes, e.g. {@code "+61412345678"} becomes
285	     * {@code "+61 412 345 678"} (see {@link E164Telephone#toDisplay}). The raw {@code telephone}
286	     * is left in E.164 form. Returns {@code null} when the owner or its telephone is absent.
287	     */
288	    default String formatTelephoneDisplay(Owner owner) {
289	        if (owner == null) {
290	            return null;
291	        }
292	        return E164Telephone.toDisplay(owner.getTelephone());
293	    }
294	
295	    /**
296	     * Compose an owner's salutation as its {@code title} followed by a single space and the
297	     * last name (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the
298	     * salutation is just the last name. Returns {@code null} when the owner is {@code null}.
299	     */
300	    default String formatSalutation(Owner owner) {
301	        if (owner == null) {
302	            return null;
303	        }
304	        String title = owner.getTitle();
305	        if (title == null || title.trim().isEmpty()) {
306	            return owner.getLastName();
307	        }
308	        return title + " " + owner.getLastName();
309	    }
310	
311	    /**
312	     * Build a link to an owner's own resource, formed as {@code "/api/owners/"} followed by the
313	     * owner's id. Returns {@code null} when the owner or its id is absent, since the link cannot
314	     * be formed without an id.
315	     */
316	    default String formatSelfLink(Owner owner) {
317	        if (owner == null || owner.getId() == null) {
318	            return null;
319	        }
320	        return "/api/owners/" + owner.getId();
321	    }
322	
323	    /**
324	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
325	     */
326	    default String formatDisplayName(Owner owner) {
327	        if (owner == null) {
328	            return null;
329	        }
330	        return owner.getLastName() + ", " + owner.getFirstName();
331	    }
332	
333	    /**
334	     * Format an owner's initials as the upper-cased first letters of the first and last
335	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
336	     */
337	    default String formatInitials(Owner owner) {
338	        if (owner == null) {
339	            return null;
340	        }
341	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
342	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
343	    }
344	
345	    Owner toOwner(OwnerDto ownerDto);
346	
347	    @Mapping(target = "id", ignore = true)
348	    @Mapping(target = "pets", ignore = true)
349	    @Mapping(target = "namesakeCount", ignore = true)
350	    @Mapping(target = "bulkSignupWarning", ignore = true)
351	    @Mapping(target = "capacityWarning", ignore = true)
352	    @Mapping(target = "possibleDuplicate", ignore = true)
353	    @Mapping(target = "possibleDuplicateOf", ignore = true)
354	    @Mapping(target = "membershipLevelCap", ignore = true)
355	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
356	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
357	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
358	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
359	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
360	    Owner toOwner(OwnerFieldsDto ownerDto);
361	
362	    /**
363	     * Normalize a postal address for storage into its canonical form (see
364	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
365	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
366	     * automatic method selection, so it only runs where a mapping explicitly references it via
367	     * {@code qualifiedByName}.
368	     */
369	    @Named("normalizeAddress")
370	    default String normalizeAddress(String address) {
371	        return AddressNormalizer.normalize(address);
372	    }
373	
374	    /**
375	     * Compose the single stored/returned {@code address} from whichever address fields the request
376	     * supplies, preferring the structured form. When a non-blank {@code addressLine1} is present the
377	     * composed value is the normalized {@code addressLine1} (see {@link AddressNormalizer}), with a
378	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
379	     * present; otherwise it falls back to the normalized flat {@code address}. This keeps everything
380	     * that reads the stored address consistent regardless of which form the caller used.
381	     */
382	    default String composeAddress(OwnerFieldsDto ownerDto) {
383	        if (ownerDto == null) {
384	            return null;
385	        }
386	        String line1 = ownerDto.getAddressLine1();
387	        if (line1 != null && !line1.trim().isEmpty()) {
388	            String composed = AddressNormalizer.normalize(line1);
389	            String line2 = ownerDto.getAddressLine2();
390	            if (line2 != null && !line2.trim().isEmpty()) {
391	                composed = composed + " " + AddressNormalizer.normalize(line2);
392	            }
393	            return composed;
394	        }
395	        return AddressNormalizer.normalize(ownerDto.getAddress());
396	    }
397	
398	    /**
399	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
400	     * The requirement that a valid E.164 number can be formed is enforced separately by
401	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
402	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
403	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
404	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
405	     */
406	    @Named("normalizeTelephone")
407	    default String normalizeTelephone(String telephone) {
408	        return E164Telephone.normalize(telephone);
409	    }
410	
411	    /**
412	     * Normalize an email address for storage by lower-casing it, so it is persisted and
413	     * returned in a canonical form regardless of the casing supplied by the caller.
414	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
415	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
416	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
417	     */
418	    @Named("normalizeEmail")
419	    default String normalizeEmail(String email) {
420	        return email == null ? null : email.toLowerCase();
421	    }
422	
423	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
424	
425	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
426	
427	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
428	        OwnerPageDto ownerPageDto = new OwnerPageDto();
429	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
430	        ownerPageDto.setPage(ownerPage.getNumber());
431	        ownerPageDto.setSize(ownerPage.getSize());
432	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
433	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
434	        return ownerPageDto;
435	    }
436	}
